CREATE TABLE "financial_accounts" ("id" UUID NOT NULL, "user_id" UUID NOT NULL, "created_at" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "financial_accounts_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "financial_accounts_user_id_key" ON "financial_accounts"("user_id");
ALTER TABLE "financial_accounts" ADD CONSTRAINT "financial_accounts_user_id_fkey" FOREIGN KEY ("user_id") REFERENCES "users"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
CREATE TABLE "financial_account_keys" ("id" UUID NOT NULL, "account_id" UUID NOT NULL, "key" TEXT NOT NULL, "created_at" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "financial_account_keys_pkey" PRIMARY KEY ("id")); CREATE UNIQUE INDEX "financial_account_keys_key_key" ON "financial_account_keys"("key"); ALTER TABLE "financial_account_keys" ADD CONSTRAINT "financial_account_keys_account_id_fkey" FOREIGN KEY ("account_id") REFERENCES "financial_accounts"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
CREATE TABLE "entitlement_definitions" ("key" TEXT NOT NULL, "description" TEXT NOT NULL, "unit" TEXT NOT NULL, "reset_strategy" TEXT NOT NULL DEFAULT 'never', "reset_interval_seconds" INTEGER, "created_at" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "entitlement_definitions_pkey" PRIMARY KEY ("key"));
CREATE TABLE "products" ("id" UUID NOT NULL, "key" TEXT NOT NULL, "name" TEXT NOT NULL, "risk_level" TEXT NOT NULL, "active" BOOLEAN NOT NULL DEFAULT true, "created_at" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" TIMESTAMPTZ(3) NOT NULL, CONSTRAINT "products_pkey" PRIMARY KEY ("id")); CREATE UNIQUE INDEX "products_key_key" ON "products"("key");
CREATE TABLE "prices" ("id" UUID NOT NULL, "product_id" UUID NOT NULL, "currency" CHAR(3) NOT NULL, "unit_amount_minor" BIGINT NOT NULL, "frequency" TEXT NOT NULL, "interval_count" INTEGER NOT NULL DEFAULT 1, "trial_days" INTEGER NOT NULL DEFAULT 0, "active" BOOLEAN NOT NULL DEFAULT true, "created_at" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "prices_pkey" PRIMARY KEY ("id")); CREATE INDEX "prices_product_id_active_idx" ON "prices"("product_id", "active"); ALTER TABLE "prices" ADD CONSTRAINT "prices_product_id_fkey" FOREIGN KEY ("product_id") REFERENCES "products"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
CREATE TABLE "product_add_ons" ("id" UUID NOT NULL, "product_id" UUID NOT NULL, "addon_product_id" UUID NOT NULL, "created_at" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "product_add_ons_pkey" PRIMARY KEY ("id")); CREATE UNIQUE INDEX "product_add_ons_product_id_addon_product_id_key" ON "product_add_ons"("product_id", "addon_product_id"); ALTER TABLE "product_add_ons" ADD CONSTRAINT "product_add_ons_product_id_fkey" FOREIGN KEY ("product_id") REFERENCES "products"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "product_add_ons" ADD CONSTRAINT "product_add_ons_addon_product_id_fkey" FOREIGN KEY ("addon_product_id") REFERENCES "products"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
CREATE TABLE "price_entitlements" ("price_id" UUID NOT NULL, "entitlement_key" TEXT NOT NULL, "quantity" BIGINT, CONSTRAINT "price_entitlements_pkey" PRIMARY KEY ("price_id", "entitlement_key")); ALTER TABLE "price_entitlements" ADD CONSTRAINT "price_entitlements_price_id_fkey" FOREIGN KEY ("price_id") REFERENCES "prices"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "price_entitlements" ADD CONSTRAINT "price_entitlements_entitlement_key_fkey" FOREIGN KEY ("entitlement_key") REFERENCES "entitlement_definitions"("key") ON DELETE RESTRICT ON UPDATE CASCADE;
CREATE TABLE "entitlements" ("id" UUID NOT NULL, "account_id" UUID NOT NULL, "key" TEXT NOT NULL, "quantity" BIGINT, "starts_at" TIMESTAMPTZ(3) NOT NULL, "ends_at" TIMESTAMPTZ(3), "revoked_at" TIMESTAMPTZ(3), "product_id" UUID, "price_id" UUID, CONSTRAINT "entitlements_pkey" PRIMARY KEY ("id")); CREATE INDEX "entitlements_account_id_key_starts_at_ends_at_idx" ON "entitlements"("account_id", "key", "starts_at", "ends_at"); ALTER TABLE "entitlements" ADD CONSTRAINT "entitlements_account_id_fkey" FOREIGN KEY ("account_id") REFERENCES "financial_accounts"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
CREATE TABLE "usage_records" ("id" UUID NOT NULL, "account_id" UUID NOT NULL, "entitlement_key" TEXT NOT NULL, "quantity" BIGINT NOT NULL, "idempotency_key" TEXT NOT NULL, "occurred_at" TIMESTAMPTZ(3) NOT NULL, CONSTRAINT "usage_records_pkey" PRIMARY KEY ("id")); CREATE UNIQUE INDEX "usage_records_idempotency_key_key" ON "usage_records"("idempotency_key"); CREATE INDEX "usage_records_account_id_entitlement_key_occurred_at_idx" ON "usage_records"("account_id", "entitlement_key", "occurred_at"); ALTER TABLE "usage_records" ADD CONSTRAINT "usage_records_account_id_fkey" FOREIGN KEY ("account_id") REFERENCES "financial_accounts"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
CREATE TABLE "wallet_entries" ("id" UUID NOT NULL, "account_id" UUID NOT NULL, "currency" CHAR(3) NOT NULL, "amount_minor" BIGINT NOT NULL, "type" TEXT NOT NULL, "idempotency_key" TEXT NOT NULL, "occurred_at" TIMESTAMPTZ(3) NOT NULL, CONSTRAINT "wallet_entries_pkey" PRIMARY KEY ("id")); CREATE UNIQUE INDEX "wallet_entries_idempotency_key_key" ON "wallet_entries"("idempotency_key"); CREATE INDEX "wallet_entries_account_id_currency_occurred_at_idx" ON "wallet_entries"("account_id", "currency", "occurred_at"); ALTER TABLE "wallet_entries" ADD CONSTRAINT "wallet_entries_account_id_fkey" FOREIGN KEY ("account_id") REFERENCES "financial_accounts"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
CREATE TABLE "payment_method_tokens" ("id" UUID NOT NULL, "account_id" UUID NOT NULL, "provider" TEXT NOT NULL, "token_reference" TEXT NOT NULL, "brand" TEXT, "last4" CHAR(4), "expires_month" INTEGER, "expires_year" INTEGER, "revoked_at" TIMESTAMPTZ(3), "created_at" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "payment_method_tokens_pkey" PRIMARY KEY ("id")); CREATE UNIQUE INDEX "payment_method_tokens_provider_token_reference_key" ON "payment_method_tokens"("provider", "token_reference");
ALTER TABLE "payment_method_tokens" ADD CONSTRAINT "payment_method_tokens_account_id_fkey" FOREIGN KEY ("account_id") REFERENCES "financial_accounts"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
CREATE TABLE "subscriptions" ("id" UUID NOT NULL, "account_id" UUID NOT NULL, "product_id" UUID NOT NULL, "price_id" UUID NOT NULL, "provider" TEXT, "provider_reference" TEXT, "status" TEXT NOT NULL, "trial_ends_at" TIMESTAMPTZ(3), "current_period_ends_at" TIMESTAMPTZ(3), CONSTRAINT "subscriptions_pkey" PRIMARY KEY ("id")); CREATE INDEX "subscriptions_account_id_status_idx" ON "subscriptions"("account_id", "status");
ALTER TABLE "subscriptions" ADD CONSTRAINT "subscriptions_account_id_fkey" FOREIGN KEY ("account_id") REFERENCES "financial_accounts"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
CREATE TABLE "invoices" ("id" UUID NOT NULL, "account_id" UUID NOT NULL, "currency" CHAR(3) NOT NULL, "total_minor" BIGINT NOT NULL, "status" TEXT NOT NULL, "provider" TEXT, "provider_reference" TEXT, "due_at" TIMESTAMPTZ(3), "created_at" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "invoices_pkey" PRIMARY KEY ("id")); CREATE INDEX "invoices_account_id_status_idx" ON "invoices"("account_id", "status");
ALTER TABLE "invoices" ADD CONSTRAINT "invoices_account_id_fkey" FOREIGN KEY ("account_id") REFERENCES "financial_accounts"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
CREATE TABLE "dunning_attempts" ("id" UUID NOT NULL, "invoice_id" UUID NOT NULL, "attempt_number" INTEGER NOT NULL, "status" TEXT NOT NULL, "failure_category" TEXT, "provider_failure_code" TEXT, "requires_customer_action" BOOLEAN NOT NULL DEFAULT false, "next_attempt_at" TIMESTAMPTZ(3), "provider_event_id" TEXT, "created_at" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "dunning_attempts_pkey" PRIMARY KEY ("id")); CREATE UNIQUE INDEX "dunning_attempts_invoice_id_attempt_number_key" ON "dunning_attempts"("invoice_id", "attempt_number"); CREATE INDEX "dunning_attempts_invoice_id_status_next_attempt_at_idx" ON "dunning_attempts"("invoice_id", "status", "next_attempt_at");
CREATE TABLE "coupons" ("id" UUID NOT NULL, "code" TEXT NOT NULL, "percent_off" INTEGER, "amount_off_minor" BIGINT, "currency" CHAR(3), "max_redemptions" INTEGER, "redeem_by" TIMESTAMPTZ(3), "active" BOOLEAN NOT NULL DEFAULT true, CONSTRAINT "coupons_pkey" PRIMARY KEY ("id")); CREATE UNIQUE INDEX "coupons_code_key" ON "coupons"("code");
CREATE TABLE "payment_provider_events" ("id" UUID NOT NULL, "provider" TEXT NOT NULL, "event_id" TEXT NOT NULL, "type" TEXT NOT NULL, "occurred_at" TIMESTAMPTZ(3) NOT NULL, "account_key" TEXT, "payload_reference" TEXT NOT NULL, "received_at" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "payment_provider_events_pkey" PRIMARY KEY ("id")); CREATE UNIQUE INDEX "payment_provider_events_provider_event_id_key" ON "payment_provider_events"("provider", "event_id");
ALTER TABLE "payment_provider_events" ADD COLUMN "object_id" TEXT, ADD COLUMN "object_status" TEXT, ADD COLUMN "provider_customer_id" TEXT;
ALTER TABLE "usage_records" ADD COLUMN "reversal_of_id" UUID;
ALTER TABLE "usage_records" ADD CONSTRAINT "usage_records_reversal_of_id_fkey" FOREIGN KEY ("reversal_of_id") REFERENCES "usage_records"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
CREATE INDEX "usage_records_reversal_of_id_idx" ON "usage_records"("reversal_of_id");
ALTER TABLE "invoices" ADD COLUMN "last_provider_event_at" TIMESTAMPTZ(3);
ALTER TABLE "subscriptions" ADD COLUMN "last_provider_event_at" TIMESTAMPTZ(3);
ALTER TABLE "payment_provider_events" ADD COLUMN "payment_status" TEXT;
CREATE UNIQUE INDEX "invoices_provider_provider_reference_key" ON "invoices"("provider", "provider_reference");
CREATE UNIQUE INDEX "subscriptions_provider_provider_reference_key" ON "subscriptions"("provider", "provider_reference");
ALTER TABLE "entitlement_definitions" ADD CONSTRAINT "entitlement_definitions_reset_check" CHECK (("reset_strategy" = 'rolling' AND "reset_interval_seconds" >= 60) OR ("reset_strategy" IN ('never', 'calendar_day', 'calendar_week', 'calendar_month') AND "reset_interval_seconds" IS NULL));
ALTER TABLE "prices" ADD CONSTRAINT "prices_amount_check" CHECK ("unit_amount_minor" >= 0 AND "interval_count" > 0 AND "trial_days" >= 0 AND "currency" ~ '^[A-Z]{3}$');
ALTER TABLE "price_entitlements" ADD CONSTRAINT "price_entitlements_quantity_check" CHECK ("quantity" IS NULL OR "quantity" > 0);
ALTER TABLE "entitlements" ADD CONSTRAINT "entitlements_range_check" CHECK (("quantity" IS NULL OR "quantity" > 0) AND ("ends_at" IS NULL OR "ends_at" > "starts_at"));
ALTER TABLE "usage_records" ADD CONSTRAINT "usage_records_quantity_check" CHECK (("reversal_of_id" IS NULL AND "quantity" > 0) OR ("reversal_of_id" IS NOT NULL AND "quantity" < 0));
ALTER TABLE "wallet_entries" ADD CONSTRAINT "wallet_entries_amount_check" CHECK ("amount_minor" <> 0 AND "currency" ~ '^[A-Z]{3}$' AND (("type" = 'credit' AND "amount_minor" > 0) OR ("type" = 'debit' AND "amount_minor" < 0) OR "type" = 'adjustment'));
ALTER TABLE "payment_method_tokens" ADD CONSTRAINT "payment_method_tokens_display_check" CHECK (("last4" IS NULL OR "last4" ~ '^[0-9]{4}$') AND ("expires_month" IS NULL OR "expires_month" BETWEEN 1 AND 12) AND ("expires_year" IS NULL OR "expires_year" BETWEEN 2000 AND 2200));
ALTER TABLE "invoices" ADD CONSTRAINT "invoices_amount_check" CHECK ("total_minor" >= 0 AND "currency" ~ '^[A-Z]{3}$');
ALTER TABLE "dunning_attempts" ADD CONSTRAINT "dunning_attempts_number_check" CHECK ("attempt_number" > 0);
ALTER TABLE "coupons" ADD CONSTRAINT "coupons_discount_check" CHECK ((("percent_off" BETWEEN 1 AND 100 AND "amount_off_minor" IS NULL AND "currency" IS NULL) OR ("percent_off" IS NULL AND "amount_off_minor" > 0 AND "currency" ~ '^[A-Z]{3}$')) AND ("max_redemptions" IS NULL OR "max_redemptions" > 0));
